/**
 * Renders docs/reference/configuration.md from the catalog (`pnpm --filter @landflow/web gen:config-docs` writes it;
 * test/config-catalog.test.ts fails when the committed page differs). Not exported from the config index: only the
 * script and the test use it.
 */
import { CONFIG_CATALOG, CONFIG_GROUPS, type ConfigGroup, type ConfigVariable } from './catalog';

const INTRO = `# Configuration

<!-- Generated by \`pnpm --filter @landflow/web gen:config-docs\` from apps/web/src/lib/server/config/catalog.ts: edit the catalog, not this page. -->

The host's environment variables, with their defaults. The compose stacks set them from \`deploy/.env\`
([deployment.md](../deployment.md)); plugins read their own, listed in the last table and in each SDK's README. Part of
the [Landflow docs](../README.md).

Flags accept \`1,true,yes,on\` and \`0,false,no,off\` (any case); that holds for every flag read through
\`lib/server/config\`, the SAML and mail ones included. A number that does not parse, or a flag that is neither, falls
back to its default with one warning in the log (\`config.invalid\`, naming the variable) instead of breaking a timer;
numbers are clamped to a sensible minimum. Read at call time, so a changed value is seen without an import-time
snapshot.

Variables marked *(secret)* are shown as \`[set]\` in the effective configuration and refused with a development value in
the production profile; marked *(required in production)* or *(recommended in production)*, the production profile
refuses to boot or warns without them ("Production profile" in [deployment.md](../deployment.md)). A deprecated alias
still works.
`;

const PLUGIN_NOTE = `Plugins read these themselves; the host does not. \`plugins/agent-shell\` (HTTP 7114, gRPC 7214; limits in \`src/shell.ts\`: command 8,000 characters, seeds 200 files and 2 MB, output 64 KB default and 512 KB ceiling per stream, filesystem 4 MB default and 32 MB ceiling, time 10 s default and 60 s ceiling, 64 kept runs, 30 minutes idle) and \`plugins/ai-sdk\` (HTTP 7115, gRPC 7215) have no variable of their own beyond the usual plugin variables and \`OTEL_*\`. Credential types of the AI SDK plugin: \`aiSdkOllamaApi\`, \`aiSdkOpenAiCompatibleApi\`, \`aiSdkAnthropicApi\`, \`aiSdkGoogleApi\`. AI Agent options \`toolImagesKept\` (Tool Images to Keep, default 2) and \`toolImages\` (\`auto\`, \`send\`, \`text\`) are node options, not variables ([features/ai.md](../features/ai.md)).
`;

function label(variable: ConfigVariable): string {
  const marks = [variable.secret && 'secret', variable.profile === 'required-in-production' && 'required in production', variable.profile === 'recommended-in-production' && 'recommended in production'].filter(Boolean);
  return `\`${variable.name}\`${marks.length ? ` *(${marks.join(', ')})*` : ''}`;
}

function describe(variable: ConfigVariable): string {
  const notes: string[] = [];
  if (variable.aliases?.length) notes.push(`Deprecated alias: ${variable.aliases.map((a) => `\`${a}\``).join(', ')}.`);
  if (variable.readBy === 'both') notes.push('Also read by plugins.');
  return [variable.description.replace(/\|/g, '\\|'), ...notes].join(' ');
}

/** Consecutive variables of one group with the same description share a row (the ones documented together). */
function rows(variables: readonly ConfigVariable[]): string[] {
  const out: string[] = [];
  for (let i = 0; i < variables.length; ) {
    let j = i + 1;
    while (j < variables.length && variables[j]!.description === variables[i]!.description) j++;
    const run = variables.slice(i, j);
    const defaults = run.map((v) => v.default);
    const shown = new Set(defaults).size === 1 ? defaults[0]! : defaults.join(' / ');
    out.push(`| ${run.map(label).join(' / ')} | ${shown.replace(/\|/g, '\\|')} | ${describe(run[0]!)} |`);
    i = j;
  }
  return out;
}

export function renderConfigDocs(): string {
  const parts = [INTRO];
  for (const group of Object.keys(CONFIG_GROUPS) as ConfigGroup[]) {
    const variables = CONFIG_CATALOG.filter((v) => v.group === group);
    if (!variables.length) continue;
    parts.push(`## ${CONFIG_GROUPS[group]}\n`);
    if (group === 'plugin') parts.push(PLUGIN_NOTE);
    parts.push(['| Variable | Default | What it does |', '|---|---|---|', ...rows(variables)].join('\n') + '\n');
  }
  return parts.join('\n');
}
